// that preserves BOTH real newlines and backslashes (\newcommand, \textbf, \tiny).
const resumeLatex = String.raw`%-------------------------
% Resume of Sanat Tudu
% Based on "Rezume" by Nanu Panchamurthy (MIT), itself based on github.com/sb2nov/resume
% One-page version: single-column, ATS-friendly layout (no tables for content),
% projects section showcasing system design, condensed experience.
%-------------------------

%------------PACKAGES----------------
