\usepackage{latexsym}
\usepackage{marvosym}
\usepackage[empty]{fullpage}
\usepackage[hidelinks]{hyperref}
\usepackage[normalem]{ulem}
\usepackage[english]{babel}
%-----------------------------------------

\input glyphtounicode % maps glyphs to unicode so ATS parsers read the text correctly
\pdfgentounicode=1
\pdfinterwordspaceon % write real space characters into the PDF so words never run together
\hyphenpenalty=10000 \exhyphenpenalty=10000 % never hyphenate (ATS reads "idem-potency" as two words)

%----------FONT OPTIONS-------------------
\usepackage[T1]{fontenc} % real ~ glyph and clean text extraction for ATS
\usepackage[default]{sourcesanspro}
\urlstyle{same}
%-----------------------------------------

%----------MARGIN OPTIONS-----------------
\pagestyle{fancy}
\fancyhf{}
\renewcommand{\headrulewidth}{0in}
\renewcommand{\footrulewidth}{0in}
\setlength{\tabcolsep}{0in}

\addtolength{\oddsidemargin}{-0.5in}
\addtolength{\topmargin}{-0.95in}
\addtolength{\textwidth}{1.0in}
\addtolength{\textheight}{2.0in}

\raggedbottom{}
\raggedright{}
