%--------SECTIONING COMMANDS---------
\titleformat{\section}
  {\large\bfseries}{}
    {0em}{\color{blue}\MakeUppercase}[\color{black}\titlerule\vspace{0pt}]
\titlespacing*{\section}{0pt}{2pt}{1pt}
%-------------------------------------

%--------REDEFINITIONS----------------
\renewcommand\labelitemii{$\vcenter{\hbox{\tiny$\bullet$}}$}
\renewcommand{\ULdepth}{2pt}
%-------------------------------------

%--------CUSTOM COMMANDS--------------
% One bullet point
\newcommand{\resumeItem}[1]{
  \item\small{#1}
}

\newcommand{\resumeItemListStart}{\begin{itemize}[rightmargin=0.11in, topsep=1pt, itemsep=0pt, parsep=0pt, partopsep=0pt]}
\newcommand{\resumeItemListEnd}{\end{itemize}}

