\newcommand{\resumeRole}[2]{
  \item
  \textit{\small #1} \hfill \textit{\small #2}
}

% Project heading: bold name | stack
\newcommand{\resumeProjectHeading}[2]{
  \Needspace{3\baselineskip}
  \item
  \textbf{#1} \small{$|$ \textit{#2}}
}

\newcommand{\resumeSubHeadingListStart}{\begin{itemize}[leftmargin=0.15in, label={}, topsep=0pt, itemsep=0pt, parsep=0pt]}
\newcommand{\resumeSubHeadingListEnd}{\end{itemize}}
\newcommand{\resumeHeadingListStart}{\begin{itemize}[leftmargin=0.15in, label={}, topsep=0pt, itemsep=0pt, parsep=0pt]}
