%-----------EDUCATION-------------------------
\section{Education}
  \resumeHeadingListStart{}
    \item \textbf{Indian Institute of Technology Bhilai} -- B.Tech in Data Science and Artificial Intelligence, 7.9 CGPA \hfill Sep 2020 -- May 2024
