if (!resumeLatex.includes('\n')) {
  throw new Error('resumeLatex has no real line breaks - it got flattened somewhere.');
}

// The item is rebuilt rather than replaced: the uploaded .tex / .pdf parts
// are in item.binary and the extract nodes further down still need them.
const item = $input.first();
return [{
  json: { ...item.json, resumeLatex, resumeLines: resumeLatex.split('\n').length },
  binary: item.binary,
}];

// Turns one multipart request into the single row every later node reads.
// Nothing downstream touches $json.body again.
const cfg = $('Config').first().json;
const req = $('Intake').first().json;
const extracted = $input.first().json || {};
const body = req.body || {};

const str = (v) => (v === undefined || v === null ? '' : String(v)).trim();

const jd = str(body.jd);
if (!jd) throw new Error('jd (the job description) is required');
if (jd.length > 20000) throw new Error('jd is ' + jd.length + ' characters, limit is 20000');

// Which slot actually arrived decides how the resume is built:
//   tex -> rewrite the applicant's own document, keeping their layout
//   pdf -> extract the text and pour it into the house template
const hasTex = $('Resolve Upload').first().json.hasTex;
const kind = hasTex ? 'tex' : 'pdf';
const layout = hasTex ? 'applicant-template' : 'house-template';

// extractFromFile names its output differently per operation.
const extractedText = String(extracted.baseTex || extracted.text || '').trim();
if (!extractedText) {
  throw new Error('could not read any text out of the uploaded ' + kind + ' file');
}
if (hasTex && !extractedText.includes('\\documentclass')) {
  throw new Error('the uploaded .tex has no \\documentclass - it is not a full LaTeX document');
}

// A .tex is tailored in place. A PDF has no layout to keep, so the house
// template becomes the skeleton and the extracted text becomes the facts.
const baseLatex = hasTex ? extractedText : cfg.resumeLatex;
const extractedFacts = hasTex ? '' : extractedText;

const company = str(body.company) || 'Unknown Company';
const title = str(body.title) || 'Unspecified Role';

// Drive folder names: no path separators (they would silently nest), no
// leading/trailing dots or spaces, and a cap so a pasted JD title cannot
// produce an unusable folder.
const folderSafe = (s, fallback) => {
  const v = String(s).replace(/[\\/]+/g, '-').replace(/\s+/g, ' ')
    .replace(/^[.\s]+|[.\s]+$/g, '').slice(0, 120).trim();
  return v || fallback;
};

const slug = (company + '-' + title).toLowerCase()
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'job';

// Unique per execution, and what the app stores as external_job_id.
const jobId = 'job-' + $execution.id + '-' + Date.now().toString(36);

console.log('job ' + jobId + ': ' + company + ' / ' + title +
  ' (' + kind + ', ' + layout + ', jd ' + jd.length + ' chars)');

return [{ json: {
  jobId,
  kind,
  layout,
  company,
  title,
  // Named 'description' because the cover-letter prompt and the tailoring
  // prompt both already read that field.
  description: jd,
  skills: str(body.skills),
  companyFolderName: folderSafe(company, 'Unknown Company'),
  roleFolderName: folderSafe(title, 'Unspecified Role'),
  baseLatex,
  extractedFacts,
  slug,
  filename: 'resume-' + slug + '.tex',
}}];

// Decides whether the company folder already exists, without the 'contains'
// ambiguity of the Drive node. 0 matches -> create it. More than one match is
// a Drive problem we cannot resolve, so we take the first and say so loudly.
const job = $('Intake Normalise').first().json;
const res = $input.first().json || {};
const body = res.body || res;
const files = (body && body.files) || [];

if (files.length > 1) {
  console.log('WARNING job ' + job.jobId + ': ' + files.length + ' folders named "' +
    job.companyFolderName + '" - using the first. Fix the duplicates in Drive.');
}

return [{ json: {
  ...job,
  folderFound: files.length > 0,
  companyFolderId: files.length ? files[0].id : '',
}}];

// Both branches land here, and they arrive with different shapes: the "found"
// branch still carries the whole job row, while the "created" branch carries
// nothing but Drive's file metadata. So the row is re-read from Intake
// Normalise rather than inherited, and only the folder id is taken from the
// incoming item.
const job = $('Intake Normalise').first().json;
const item = $input.first().json || {};
const companyFolderId = item.companyFolderId || item.id || '';

if (!companyFolderId) {
  throw new Error('could not resolve a company folder for job ' + job.jobId +
    ' - refusing to continue, Drive would put the files in My Drive root.');
}

return [{ json: { ...job, companyFolderId } }];

// Same find-or-create decision one level down: <company>/<role>/.
// Two jobs for the same role at the same company deliberately share a folder
// and overwrite, so re-running a role does not litter Drive with copies.
const job = $('Company Folder').first().json;
const res = $input.first().json || {};
const body = res.body || res;
const files = (body && body.files) || [];

if (files.length > 1) {
  console.log('WARNING job ' + job.jobId + ': ' + files.length + ' folders named "' +
    job.roleFolderName + '" under ' + job.companyFolderName + ' - using the first.');
}

return [{ json: {
  ...job,
  roleFolderFound: files.length > 0,
  roleFolderId: files.length ? files[0].id : '',
}}];

// Same shape problem as Company Folder, one level down. This node's output is
// the destination every artifact is uploaded to: <company>/<role>/.
const job = $('Company Folder').first().json;
const item = $input.first().json || {};
const roleFolderId = item.roleFolderId || item.id || '';

if (!roleFolderId) {
  throw new Error('could not resolve a role folder for job ' + job.jobId +
    ' - refusing to continue, Drive would put the files in My Drive root.');
}

return [{ json: { ...job, roleFolderId } }];

// The job's state lives in status.json inside its own Drive folder, not in
// n8n. That is what lets the status webhook answer after an n8n restart, and
// what lets any number of n8n workers serve the same job.
//
// Written BEFORE the webhook responds, so the app's first poll can never 404.
const job = $('Role Folder').first().json;

return [{ json: {
  ...job,
  statusContent: JSON.stringify({
    status: 'running',
    jobId: job.jobId,
    company: job.company,
    title: job.title,
    kind: job.kind,
    layout: job.layout,
    folderId: job.roleFolderId,
    folderUrl: 'https://drive.google.com/drive/folders/' + job.roleFolderId,
    startedAt: new Date().toISOString(),
    files: [],
  }, null, 2),
  statusFilename: 'status.json',
}}];

// When the request carried a PDF alongside a .tex, the PDF is kept in the
// folder as a reference copy - it is the document the applicant actually has.
// Returning an empty array is how this branch opts out: no PDF, no upload,
// and nothing else hangs off it.
const src = $('Resolve Upload').first();
const job = $('Role Folder').first().json;
const pdf = src.binary && src.binary.pdf;

if (!pdf) return [];

return [{
  json: { ...job, sourcePdfName: 'source-resume.pdf' },
  binary: { data: pdf },
}];

const job = $('Build Prompt').first().json;
const res = $input.first().json;

let text =
  (res && res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content)
  || '';

text = String(text).trim();

// Strip ```latex ... ``` fences if the model added them anyway.
text = text.replace(/^```(?:latex|tex)?\s*/i, '').replace(/```\s*$/, '').trim();

// Normalise Windows line endings ONLY.
// Never touch backslash sequences: \n, \t, \r are the opening characters of
// real LaTeX commands (\newcommand, \textbf, \tiny, \tabcolsep, \raggedright...).
text = text.replace(/\r\n/g, '\n');

if (!text.includes('\\documentclass')) {
  throw new Error('Model did not return a full LaTeX document for job ' + job.jobId + '. Got: ' + text.slice(0, 200));
}

const { payload, baseLatex, extractedFacts, ...row } = job;

return [{
  json: {
    ...row,
    latex: text,
    // companyFolderName / roleFolderName / filename were all settled by Intake
    // Normalise before the folders were created, so they are inherited as-is.
    companyFolderId: $('Company Folder').first().json.companyFolderId,
    roleFolderId: $('Role Folder').first().json.roleFolderId,
  },
}];

// Entry point of the compile loop. Carries the job, the LaTeX and the attempt
// counter; the loop re-enters Compile PDF with this same shape.
const job = $('Clean LaTeX').first().json;
const companyFolderId = $('Company Folder').first().json.companyFolderId || '';
const roleFolderId = $('Role Folder').first().json.roleFolderId || '';

// Everything goes into <company>/<role>/ so two roles at one company
// cannot collide on SanatTudu.pdf. An unresolved folder id would NOT fail the
// upload - Drive would quietly drop the files into My Drive root instead.
if (!roleFolderId) {
  throw new Error('No role folder id for job ' + job.jobId + ' (company folder ' +
    (companyFolderId || 'unknown') + '). Refusing to upload to the Drive root.');
}

return [{ json: {
  ...job,
  companyFolderId,
  roleFolderId,
  attempt: 1,
  compileLog: '',
}}];

// Both the first attempt and every retry pass through here, so this node's run
// index always matches Compile PDF's. That makes $('Compile Input').first() the
// item that was actually compiled - the HTTP node's own output is just headers
// and a binary, and carries none of the row.
return $input.all();

// The single source of truth after the compile loop. Everything downstream must
// read from HERE, not from Clean LaTeX: on a retry Clean LaTeX still holds the
// FIRST, broken attempt while the PDF came from the fixed LaTeX.
const item = $input.first();
const compiled = $('Compile Input').first().json;
const bytes = Number((item.json && item.json.headers && item.json.headers['content-length']) || 0);

console.log('job ' + compiled.jobId + ': compiled on attempt ' + (compiled.attempt || 1) +
  (bytes ? ' (' + bytes + ' bytes)' : ''));

return [{
  json: {
    ...compiled,
    pdfBytes: bytes,
    pdfName: $('Config').first().json.pdfName,
  },
  binary: item.binary,
}];

// The Drive upload replaced our item with file metadata and consumed the PDF
// binary, so re-emit the row before LaTeX to File builds the .tex binary.
const job = $('Compiled Resume').first().json;
const uploaded = $input.first().json || {};

return [{ json: {
  ...job,
  pdfFileId: uploaded.id || '',
  pdfWebViewLink: uploaded.webViewLink || '',
}}];

// The compiler returned a non-200. responseFormat is 'file', so even the JSON
// error body arrives as a binary - decode it here, once, so both the retry
// branch and the give-up branch have the real log.
//
// Two ways in, because which one works depends on n8n's binary data mode:
// inline base64 (the default) or a file on disk / S3.
const item = $input.first();
const job = $('Compile Input').first().json;

let raw = '';
try {
  const b = item.binary && item.binary.data;
  if (b && b.data) raw = Buffer.from(b.data, 'base64').toString('utf8');
} catch (e) { /* fall through */ }

if (!raw) {
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    raw = buf.toString('utf8');
  } catch (e) { /* fall through */ }
}

if (!raw && item.json && typeof item.json.body === 'string') raw = item.json.body;

let detail = { error: '', log: '' };
try { detail = JSON.parse(raw); }
catch (e) {
  detail.error = 'compile request failed';
  detail.log = raw ? raw.slice(0, 2000)
    : 'no response body (HTTP ' + ((item.json && item.json.statusCode) || '?') + ')';
}

// latexmk prints what matters as 'file.tex:LINE: message' or '! message'. The
// rest of the log is font loading noise, so those lines come first.
const lines = String(detail.log || '').split('\n');
const errors = lines.filter(l => /\.tex:\d+:|^!/.test(l));
const excerpt = (errors.length ? errors : lines.slice(-40)).join('\n').slice(0, 4000);

const attempt = job.attempt || 1;
console.log('job ' + job.jobId + ': compile attempt ' + attempt + ' failed (HTTP ' +
  ((item.json && item.json.statusCode) || '?') + ')\n' + excerpt);

return [{ json: {
  ...job,
  attempt,
  compileStatus: (item.json && item.json.statusCode) || 0,
  compileError: detail.error || 'compile failed',
  compileLog: excerpt,
}}];

// The compiler rejected the LaTeX. Hand the model its own broken document plus
// the real error log and ask for a minimal repair - not a rewrite.
const cfg = $('Config').first().json;
const job = $input.first().json;

const system = [
  'You fix LaTeX that failed to compile. You are given a document and the compiler log.',
  '',
  'OUTPUT FORMAT',
  '- Output ONLY the corrected, complete LaTeX document.',
  '- Start at \\documentclass and end at \\end{document}. No fences, no commentary.',
  '',
  'RULES',
  '- Fix ONLY what the log complains about. Change nothing else.',
  '- Do NOT rewrite, reword, shorten or restructure the content.',
  '- Do NOT add packages unless the log proves one is missing. The compiler has a',
  '  limited package set, so prefer removing or replacing an undefined command',
  '  over pulling in a new \\usepackage.',
  '- "Undefined control sequence" means a command was invented. Replace it with',
  '  plain text or with a command the document already defines.',
  '- Escape % $ & # _ in text. Never leave a bare < or >.',
  '- Every { must close; every \\begin must have its \\end.',
  '- The document must still fit on one page.',
].join('\n');

const user = [
  'COMPILER ERROR: ' + (job.compileError || 'compile failed'),
  '',
  '--- LOG ---',
  job.compileLog || '(no log returned)',
  '--- END LOG ---',
  '',
  '--- LATEX THAT FAILED ---',
  job.latex,
  '--- END LATEX ---',
  '',
  'Return the corrected full LaTeX document only.',
].join('\n');

return [{ json: {
  ...job,
  fixPayload: {
