// ---------- document.xml ----------
// sz is half-points (22 = 11pt); spacing/indents are twips (1440 = 1 inch).
function para(text, opts) {
  const o = opts || {};
  const runProps =
    '<w:rPr>' +
    (o.bold ? '<w:b/>' : '') +
    '<w:sz w:val="' + (o.size || 22) + '"/>' +
    '<w:szCs w:val="' + (o.size || 22) + '"/>' +
    (o.color ? '<w:color w:val="' + o.color + '"/>' : '') +
    '</w:rPr>';
  const lines = String(text).split('\n');
  const runs = lines.map((line, i) =>
    (i ? '<w:r>' + runProps + '<w:br/></w:r>' : '') +
    '<w:r>' + runProps + '<w:t xml:space="preserve">' + esc(line) + '</w:t></w:r>'
  ).join('');
  return '<w:p><w:pPr><w:spacing w:after="' + (o.after === undefined ? 160 : o.after) +
    '" w:line="276" w:lineRule="auto"/>' +
    (o.align ? '<w:jc w:val="' + o.align + '"/>' : '') +
    '</w:pPr>' + runs + '</w:p>';
}

