// Reads the marker the generator wrote. The one rule that matters here: an
// unreadable or missing marker is reported as RUNNING, never failed - the app
// treats 'failed' as terminal and would burn the job row on a transient Drive
// hiccup or on a poll that arrived a second too early.
const folderId = $('Status Webhook').first().json.params.folderId || '';
const res = $input.first().json || {};

let raw = '';
if (typeof res.body === 'string') raw = res.body;
else if (res.body && typeof res.body === 'object') raw = JSON.stringify(res.body);
else if (typeof res.data === 'string') raw = res.data;

let marker = null;
try { marker = raw ? JSON.parse(raw) : null; } catch (e) { marker = null; }

const folderUrl = 'https://drive.google.com/drive/folders/' + folderId;

if (!marker || !marker.status) {
  return [{ json: { status: 'running', folderUrl, files: [] } }];
}

return [{ json: {
  status: marker.status === 'failed' ? 'failed' : (marker.status === 'done' ? 'done' : 'running'),
  folderUrl: marker.folderUrl || folderUrl,
  files: marker.files || [],
  error: marker.error || undefined,
  compileAttempts: marker.compileAttempts,
}}];

// Finds the uploaded .tex and .pdf whatever n8n decided to call them.
//
// A multipart file is NOT guaranteed to land in a binary property named after
// its form field: depending on the n8n version it can arrive as 'tex'/'pdf' or
// as 'file0'/'file1'. Hardcoding the field name made a perfectly good request
// look like "no text could be read", so the slot is resolved from the data
// instead: exact key first, then the filename, then the mime type.
const intake = $('Intake').first();
const binary = intake.binary || {};
const keys = Object.keys(binary);

const describe = (k) => {
  const b = binary[k] || {};
  return (b.fileName || '?') + ' [' + (b.mimeType || '?') + ']';
};

const looksLike = (ext, mimes) => (k) => {
  const b = binary[k] || {};
  const name = String(b.fileName || '').toLowerCase();
  const fileExt = String(b.fileExtension || '').toLowerCase();
  const mime = String(b.mimeType || '').toLowerCase();
  return fileExt === ext || name.endsWith('.' + ext) || mimes.includes(mime);
};

const pick = (exact, ext, mimes, avoid) => {
  if (keys.includes(exact) && binary[exact]) return exact;
  const match = keys.find((k) => k !== avoid && looksLike(ext, mimes)(k));
  return match || '';
};

// A .tex is often sent as application/octet-stream or text/plain, so the
// extension is the reliable signal and the mime type is only a fallback.
const texKey = pick('tex', 'tex', ['application/x-tex', 'text/x-tex'], null);
const pdfKey = pick('pdf', 'pdf', ['application/pdf'], texKey);

if (!texKey && !pdfKey) {
  throw new Error(
    'no .tex or .pdf file was attached. Binary properties received: ' +
    (keys.length ? keys.map((k) => k + ' = ' + describe(k)).join(', ') : '(none)') +
    '. Express sends them as the form fields "tex" and "pdf".');
}

// Re-emitted under stable names so the extract nodes can keep reading 'tex'
// and 'pdf' regardless of what arrived.
const out = {};
if (texKey) out.tex = binary[texKey];
if (pdfKey) out.pdf = binary[pdfKey];

if ((texKey && texKey !== 'tex') || (pdfKey && pdfKey !== 'pdf')) {
  console.log('this n8n names multipart uploads differently: tex=' + (texKey || '-') +
    ', pdf=' + (pdfKey || '-') + ' - remapped.');
} else {
  console.log('uploads: tex=' + (texKey || '-') + ', pdf=' + (pdfKey || '-'));
}

return [{
  json: { ...$input.first().json, texKey, pdfKey, hasTex: Boolean(texKey) },
  binary: out,
}];
